<?php
/** @var array $product */
$pid=(int)$product['id'];
$price=$product['promo_price_cents']!==null?(int)$product['promo_price_cents']:(int)$product['price_cents'];
$hasPromo=$product['promo_price_cents']!==null;
$search=mb_strtolower(trim((string)($product['name'].' '.($product['description']??'').' '.($product['badge']??''))));
$stockUnavailable=(bool)($product['track_stock']??false)&&(int)($product['stock_qty']??0)<=0;
?><article class="menu-product" data-search="<?= Security::e($search) ?>"><?php if($showImages&&!empty($product['image_url'])):?><img class="product-image" src="<?= Security::e($product['image_url']) ?>" alt="<?= Security::e($product['name']) ?>" loading="lazy"><?php endif;?><div class="product-body"><div style="display:flex;justify-content:space-between;gap:8px;align-items:start"><h3><?= Security::e($product['name']) ?></h3><?php if($showBadges&&!empty($product['badge'])):?><span class="pill"><?= Security::e($product['badge']) ?></span><?php endif;?></div><?php if($showDescriptions&&!empty($product['description'])):?><div class="product-desc"><?= Security::e($product['description']) ?></div><?php endif;?><div class="product-meta"><?php if($showPreparation&&!empty($product['preparation_minutes'])):?><span class="pill">≈ <?= (int)$product['preparation_minutes'] ?> min</span><?php endif;?><?php if(!empty($product['featured'])):?><span class="pill">Destaque</span><?php endif;?><?php if($stockUnavailable):?><span class="pill">Esgotado</span><?php endif;?></div><div><?php if($hasPromo):?><span class="old-price"><?= mesa_money((int)$product['price_cents']) ?></span> <?php endif;?><span class="price"><?= mesa_money($price) ?></span></div><form method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?= $pid ?>"><?php if(!empty($groups[$pid])):?><details class="option-box"><summary>Escolher opções / adicionais</summary><?php foreach($groups[$pid] as$group):?><div class="option-group"><strong><?= Security::e($group['name']) ?><?php if((int)$group['min_select']>0):?> · obrigatório<?php endif;?></strong><?php foreach($options[(int)$group['id']]??[] as$option):$radio=(int)$group['max_select']===1;?><label class="option-row"><span><input type="<?= $radio?'radio':'checkbox' ?>" <?= $radio?'name="group_'.$group['id'].'"':'name="group_'.$group['id'].'[]"' ?> value="<?= (int)$option['id'] ?>" onchange="syncOpts(this.form,<?= (int)$group['id'] ?>)"<?= $radio&&(int)$group['min_select']>0?' required':'' ?>> <?= Security::e($option['name']) ?></span><span><?= (int)$option['price_delta_cents']===0?'':(((int)$option['price_delta_cents']>0?'+ ':'- ').mesa_money(abs((int)$option['price_delta_cents']))) ?></span></label><?php endforeach;?></div><?php endforeach;?></details><?php endif;?><div class="add-row"><input type="number" name="qty" value="1" min="1" max="50"<?= $stockUnavailable?' disabled':'' ?>><button type="submit"<?= $stockUnavailable?' disabled':'' ?>><?= $stockUnavailable?'Esgotado':'Adicionar +' ?></button></div></form></div></article>
